content.css:
.atlyn-scatter {
  font-family: "Segoe UI", sans-serif;
  color: #252423;
  overflow: hidden;
  position: relative;
  width: 100%;
  height: 100%;
  touch-action: pan-y;
  direction: ltr;
  display: flex;
  flex-direction: column;
  min-height: 0;
  min-width: 0;
}
.atlyn-scatter[dir="rtl"] {
  direction: rtl;
}
.atlyn-scatter[data-high-contrast="true"] {
  background: Canvas;
  color: CanvasText;
}
.atlyn-scatter__svg {
  display: block;
  flex: 1 1 auto;
  min-height: 0;
  min-width: 0;
  width: 100%;
}
.atlyn-scatter__message {
  font-size: 13px;
  padding: 16px;
  text-align: start;
  flex: 0 1 auto;
  min-height: 0;
  overflow: auto;
}
.atlyn-scatter__table {
  flex: 0 0 auto;
  min-height: 0;
  min-width: 0;
  overflow: auto;
  width: 100%;
}
.atlyn-scatter__semantic-table {
  border-collapse: collapse;
  font-size: 11px;
  width: 100%;
}
.atlyn-scatter__semantic-table caption {
  font-weight: 600;
  text-align: start;
}
.atlyn-scatter__semantic-table th,
.atlyn-scatter__semantic-table td {
  padding: 2px 4px;
  text-align: start;
}
.atlyn-scatter__table--visually-hidden {
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  flex: 0 0 auto;
  height: 1px;
  overflow: hidden;
  position: absolute;
  white-space: nowrap;
  width: 1px;
}
.atlyn-scatter__semantic-table--visually-hidden {
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  height: 1px;
  overflow: hidden;
  position: absolute;
  white-space: nowrap;
  width: 1px;
}
.atlyn-scatter__point:focus {
  outline: 2px solid currentColor;
  outline-offset: 2px;
}
.atlyn-scatter__point--selected {
  stroke-width: 3px;
}
.atlyn-scatter[data-reduced-motion="true"] *,
.atlyn-scatter [data-reduced-motion="true"] * {
  animation: none !important;
  transition: none !important;
}
